scripts.inline:
// HTPR-4648: only returning app users skip the marketing page (the
        // app sets the ht_in flag cookie). New visitors stay and reach the
        // demo via the Get Started buttons. ?stay always keeps the page.
        if (/(?:^|;\s*)ht_in=1(?:;|$)/.test(document.cookie) && !location.search.includes('stay')) {
          location.replace('https://app.hypertask.ai/login')
        }

(function() {
    document.addEventListener('keydown', function(e) {
      if (e.key !== 'l' && e.key !== 'L') return;
      if (e.ctrlKey || e.metaKey || e.altKey || e.repeat) return;
      var t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable)) return;
      var login = document.getElementById('login-button');
      if (login) window.location.href = login.href;
    });
  })();

(function() {
    var header = document.getElementById('main-header');
    if (header && !header.classList.contains('home-header')) {
      window.addEventListener('scroll', function() {
        if (window.scrollY > 0) {
          header.style.borderColor = 'var(--header-border)';
          header.style.transition = 'border-color 0.3s';
        } else {
          header.style.borderColor = 'transparent';
        }
      });
    }
  })();

document.querySelectorAll('[data-pricing-module]').forEach((pricing) => {
    pricing.querySelectorAll('.pricing-toggle button').forEach((button) => {
      button.addEventListener('click', () => {
        pricing.querySelectorAll('.pricing-toggle button').forEach((item) => {
          item.setAttribute('aria-pressed', 'false')
        })
        button.setAttribute('aria-pressed', 'true')

        const period = button.dataset.period
        pricing.querySelectorAll('[data-monthly]').forEach((item) => {
          item.textContent = item.dataset[period]
        })
      })
    })
  })

document.querySelectorAll('[data-install]').forEach(box => {
    const code = box.querySelector('[data-install-cmd]')
    const copy = box.querySelector('[data-install-copy]')
    box.querySelectorAll('[data-cmd]').forEach(tab => {
      tab.addEventListener('click', () => {
        box.querySelectorAll('[data-cmd]').forEach(t => t.setAttribute('aria-selected', String(t === tab)))
        code.textContent = tab.dataset.cmd || ''
        copy.textContent = 'Copy'
      })
    })
    copy.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(code.textContent || '')
        copy.textContent = 'Copied'
      } catch { copy.textContent = 'Copy failed' }
      setTimeout(() => { copy.textContent = 'Copy' }, 1800)
    })
  })

document.addEventListener('click', (event) => {
      const link = event.target instanceof Element ? event.target.closest('a[href]') : null
      if (link && link.href.startsWith('https://app.hypertask.ai')) window.fathom?.trackEvent('Sign up click')
    })

